import numpy as np
from PIL import Image
from scipy import ndimage

def load(fname):
    return np.array(Image.open(fname).convert('RGB')).astype(int)

def mask_color(a, target, tol):
    return np.abs(a - np.array(target)).sum(axis=2) <= tol

def blackmask(a, dark=110):
    return (a[:,:,0]<dark)&(a[:,:,1]<dark)&(a[:,:,2]<dark)

def white(a, tol=25):
    return mask_color(a,(255,255,255),tol)

def cc(mask, min_size=8):
    lab, n = ndimage.label(mask)
    out=[]
    for i in range(1,n+1):
        ys,xs = np.where(lab==i)
        if len(xs)<min_size: continue
        out.append(dict(cx=xs.mean(), cy=ys.mean(), size=len(xs),
                        x0=xs.min(), x1=xs.max(), y0=ys.min(), y1=ys.max()))
    return out

def to_val(tick_px, tick_val, px, scale):
    if scale=='linear':
        return tick_val[0] + (px - tick_px[0])*(tick_val[1]-tick_val[0])/(tick_px[1]-tick_px[0])
    lx0, lv0 = np.log10(tick_px[0]), np.log10(tick_val[0])
    lx1, lv1 = np.log10(tick_px[1]), np.log10(tick_val[1])
    lv = lv0 + (px-lx0)*(lv1-lv0)/(lx1-lx0)
    return 10**lv

def report(comps):
    for c in sorted(comps, key=lambda c:(c['cy'],c['cx'])):
        bw=c['x1']-c['x0']+1; bh=c['y1']-c['y0']+1
        print(f\"  cx={c['cx']:7.1f} cy={c['cy']:7.1f} size={c['size']:5d} w={bw:3d} h={bh:3d}\")
