def load(f): return np.array(Image.open(f).convert('RGB')).astype(int)

def color_masks(a):
    r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
    return {
      'black': (r<100)&(g<100)&(b<100),
      'red':   (r>140)&(r>g+40)&(r>b+40),
      'green': (g>100)&(g>r+40)&(g>b+40),
      'blue':  (b>140)&(b>r+40)&(b>g+40),
    }

def holes(a, col, exclude_boxes=(), size_lo=10, size_hi=400):
    """Return hole centers (interiors of hollow markers) for a color."""
    m=color_masks(a)[col]
    filled=ndimage.binary_fill_holes(m)
    holes=filled & ~m
    lab,n=ndimage.label(holes)
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        size=len(xs)
        if not (size_lo<=size<=size_hi): continue
        cx,cy=xs.mean(),ys.mean()
        keep=True
        for (x0,x1,y0,y1) in exclude_boxes:
            if (x0<=cx<=x1 and y0<=cy<=y1): keep=False; break
        if keep: out.append((cx,cy,size))
    return sorted(out, key=lambda t:t[0])

